//! The disk tier's contract: a byte-exact header, a name that is the lookup, and a
//! budget pass that scores rather than rotates.
//!
//! The header and payload fixtures here are hand-built rather than produced by the
//! code under test, because the whole point of both layouts is that a directory
//! written by an older build stays readable. A fixture generated by `to_bytes` would
//! keep passing no matter how the layout drifted.

use std::fs::{self, OpenOptions};
use std::io::Write as _;
use std::path::{Path, PathBuf};

use shiso_core::TokenId;
use shiso_kvstore::{
    Incoming, PathHeader, PathMismatch, PathSections, PathWords, Reason, SpillConfig, SpillHeader,
    SpillId, SpillStore, SpillWrite, decode_path, encode_path,
};

/// Bytes in the fixed header, repeated here so the fixture is checked against a
/// number this file owns rather than against the crate's own constant.
const HEADER_BYTES: usize = 48;
/// A payload big enough that three of them overflow a 1 MiB budget.
const FAT_PAYLOAD: usize = 400_000;

/// A header with every field set to something other than the default, so a field
/// written at the wrong offset shows up as a diff rather than as two zeros matching.
fn fixture_header() -> SpillHeader {
    SpillHeader {
        quant_bits: 4,
        reason: Reason::Evict.as_u8(),
        ext_flags: 0,
        model_id: 7,
        tokens: 1000,
        hits: 5,
        ctx_size: 8192,
        payload_abi: 2,
        created_at: 1_700_000_000,
        last_used: 1_700_000_600,
        payload_bytes: 4096,
    }
}

#[test]
fn the_48_byte_header_layout_is_pinned_byte_for_byte() {
    let fixture: [u8; HEADER_BYTES] = [
        0x4b, 0x56, 0x43, 0x01, 0x04, 0x03, 0x00, 0x07, 0xe8, 0x03, 0x00, 0x00, 0x05, 0x00, 0x00,
        0x00, 0x00, 0x20, 0x00, 0x00, 0x02, 0x00, 0x00, 0x00, 0x00, 0xf1, 0x53, 0x65, 0x00, 0x00,
        0x00, 0x00, 0x58, 0xf3, 0x53, 0x65, 0x00, 0x00, 0x00, 0x00, 0x00, 0x10, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00,
    ];
    assert_eq!(fixture, fixture_header().to_bytes());
    assert_eq!(fixture_header(), SpillHeader::from_bytes(&fixture));
    assert!(SpillHeader::has_magic(&fixture));
}

#[test]
fn a_header_is_restorable_only_when_it_describes_a_path_this_build_can_load() {
    let mut fixture = fixture_header().to_bytes();
    assert!(SpillHeader::from_bytes(&fixture).is_restorable());

    // An empty prefix checkpoints nothing, whatever else is right about the file.
    fixture[8..12].copy_from_slice(&0u32.to_le_bytes());
    assert!(!SpillHeader::from_bytes(&fixture).is_restorable());

    // A quantization this build cannot lay back into pages means the KV bytes would
    // be mis-parsed into garbage rows, which is worse than a miss.
    let mut fixture = fixture_header().to_bytes();
    fixture[4] = 5;
    assert!(!SpillHeader::from_bytes(&fixture).is_restorable());
    fixture[4] = 2;
    assert!(SpillHeader::from_bytes(&fixture).is_restorable());

    // A different payload ABI means the bytes behind the text are shaped differently.
    let mut fixture = fixture_header().to_bytes();
    fixture[20] = 3;
    assert!(!SpillHeader::from_bytes(&fixture).is_restorable());
}

#[test]
fn an_entry_is_named_by_the_sha1_of_its_text() {
    let dir = tempfile::tempdir().expect("tempdir");
    let store = SpillStore::open(&SpillConfig::new(dir.path(), 1)).expect("open");
    let path = store.path_of(SpillId::of(b"abc"));
    // The sha1 of "abc", from outside this crate, so the name is checked against a
    // digest this file knows rather than one the code just produced.
    assert_eq!(
        path.file_name().expect("file name"),
        "a9993e364706816aba3e25717850c26c9cd0d89d.kv"
    );
}

#[test]
fn a_written_path_reads_back_byte_for_byte() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut store = SpillStore::open(&SpillConfig::new(dir.path(), 64)).expect("open");
    let text = b"system: you are a helpful assistant\nuser: hello";
    let payload: Vec<u8> = (0..512u32)
        .map(|i| u8::try_from(i % 251).expect("fits"))
        .collect();
    let written = store
        .write(&incoming(text, &payload, Reason::Cold))
        .expect("write");
    let id = match written {
        SpillWrite::Written { id, bytes } => {
            assert_eq!(
                bytes,
                u64::try_from(HEADER_BYTES + 4 + text.len() + payload.len())
                    .expect("entry size fits")
            );
            id
        }
        SpillWrite::AlreadyStored { .. } => panic!("nothing was stored before this write"),
        // The enum is non_exhaustive, so an outside match needs the arm even though
        // there is no third outcome today.
        _ => panic!("no other outcome"),
    };
    let read = store.read(id).expect("read").expect("the entry is there");
    assert_eq!(read.text, text);
    assert_eq!(read.payload, payload);
    assert_eq!(read.header.tokens, 100);
    assert_eq!(read.header.reason, Reason::Cold.as_u8());
    assert_eq!(read.header.hits, 0, "a fresh entry has not been read yet");
    assert_eq!(store.stats().entries, 1);
}

#[test]
fn writing_the_same_path_again_writes_nothing() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut store = SpillStore::open(&SpillConfig::new(dir.path(), 64)).expect("open");
    let payload = vec![0x5au8; 64];
    store
        .write(&incoming(b"the same prompt", &payload, Reason::Cold))
        .expect("first write");
    let again = store
        .write(&incoming(b"the same prompt", &payload, Reason::Shutdown))
        .expect("second write");
    assert!(matches!(again, SpillWrite::AlreadyStored { .. }));
    assert_eq!(dir_files(dir.path()).len(), 1, "no second file");
}

#[test]
fn a_file_whose_text_does_not_hash_to_its_name_is_refused() {
    let dir = tempfile::tempdir().expect("tempdir");
    let store = SpillStore::open(&SpillConfig::new(dir.path(), 64)).expect("open");
    let id = SpillId::of(b"the name says this");
    // A file at the right name with the wrong text: a copy or a rename, not an entry.
    write_raw(
        &store.path_of(id),
        b"the contents say otherwise",
        b"payload",
    );
    let error = store.read(id).expect_err("the name is a lie");
    assert!(
        error.to_string().contains("does not match its name"),
        "expected a name mismatch, got {error}"
    );
}

#[test]
fn a_stray_file_in_the_directory_is_invisible() {
    let dir = tempfile::tempdir().expect("tempdir");
    let store = SpillStore::open(&SpillConfig::new(dir.path(), 64)).expect("open");
    fs::write(dir.path().join("notes.txt"), b"somebody's scratch file").expect("write");
    fs::write(
        dir.path()
            .join("zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz.kv"),
        b"x",
    )
    .expect("write");
    fs::create_dir(dir.path().join("subdir")).expect("mkdir");
    assert_eq!(store.stats().entries, 0);
    assert_eq!(store.stats().total_bytes, 0);
}

#[test]
fn a_write_that_could_never_fit_is_refused_before_anything_is_written() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut store = SpillStore::open(&SpillConfig::new(dir.path(), 1)).expect("open");
    let payload = vec![0u8; 2 * 1024 * 1024];
    let error = store
        .write(&incoming(
            b"too big for this budget",
            &payload,
            Reason::Cold,
        ))
        .expect_err("a 2 MiB entry cannot fit a 1 MiB budget");
    assert!(error.to_string().contains("budget is"), "got {error}");
    assert!(
        dir_files(dir.path()).is_empty(),
        "nothing may reach the disk"
    );
}

#[test]
fn a_failed_rename_leaves_no_temporary_file_behind() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut store = SpillStore::open(&SpillConfig::new(dir.path(), 64)).expect("open");
    let id = SpillId::of(b"blocked by a directory");
    // The rename is the last step of the write; making its destination an
    // unreplaceable directory fails exactly that step.
    fs::create_dir(store.path_of(id)).expect("mkdir");
    assert!(
        store
            .write(&incoming(
                b"blocked by a directory",
                b"payload",
                Reason::Cold
            ))
            .is_err()
    );
    let debris: Vec<PathBuf> = dir_files(dir.path())
        .into_iter()
        .filter(|path| {
            path.file_name()
                .is_some_and(|name| name.to_string_lossy().contains(".tmp."))
        })
        .collect();
    assert!(
        debris.is_empty(),
        "the temporary file was left behind: {debris:?}"
    );
}

#[test]
fn a_read_records_a_hit_and_refreshes_the_timestamp() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut store = SpillStore::open(&SpillConfig::new(dir.path(), 64)).expect("open");
    let id = SpillId::of(b"read me twice");
    store
        .write(&incoming(b"read me twice", b"payload", Reason::Cold))
        .expect("write");
    store.touch(id).expect("first touch");
    store.touch(id).expect("second touch");
    let header = read_raw_header(&store.path_of(id));
    assert_eq!(header.hits, 2);
    assert_ne!(header.last_used, 0);
    assert_ne!(header.created_at, 0);
}

#[test]
fn the_budget_pass_keeps_an_anchor_over_an_identical_unanchored_entry() {
    let dir = tempfile::tempdir().expect("tempdir");
    // Three equal entries in a 1 MiB budget, which is over the line by enough for
    // exactly one deletion. Two of these differ only in their reason byte, so the
    // one that goes can only have gone because of that byte.
    let mut store = SpillStore::open(&SpillConfig::new(dir.path(), 64)).expect("open");
    let anchor = write_fat(&mut store, b"anchor path", Reason::Evict, 0, AN_HOUR);
    let unanchored = write_fat(&mut store, b"shared path", Reason::AgentSystem, 0, AN_HOUR);
    let read_once = write_fat(&mut store, b"read path", Reason::Evict, 5, AN_HOUR);
    drop(store);

    let reopened = SpillStore::open(&SpillConfig::new(dir.path(), 1)).expect("reopen");
    assert_eq!(
        reopened.stats().entries,
        2,
        "exactly one entry over the budget"
    );
    assert!(reopened.stats().evictions >= 1);
    assert!(
        !reopened.contains(unanchored),
        "the unanchored entry is what goes"
    );
    assert!(
        reopened.contains(anchor),
        "an anchor with the same history is kept"
    );
    assert!(reopened.contains(read_once));
}

#[test]
fn the_budget_pass_breaks_a_tie_with_the_older_last_used() {
    let dir = tempfile::tempdir().expect("tempdir");
    // Two of these score identically - same reason, same hits, same size - so only
    // recency can decide, and the older one has to be the one deleted.
    let mut store = SpillStore::open(&SpillConfig::new(dir.path(), 64)).expect("open");
    let stale = write_fat(&mut store, b"stale entry", Reason::Cold, 0, TWO_HOURS);
    let fresh = write_fat(&mut store, b"fresh entry", Reason::Cold, 0, A_MINUTE);
    let read = write_fat(&mut store, b"read entry", Reason::Cold, 20, A_MINUTE);
    drop(store);

    let reopened = SpillStore::open(&SpillConfig::new(dir.path(), 1)).expect("reopen");
    assert_eq!(reopened.stats().entries, 2);
    assert!(
        !reopened.contains(stale),
        "the older of two equal entries goes"
    );
    assert!(reopened.contains(fresh));
    assert!(reopened.contains(read));
}

#[test]
fn a_hit_count_is_worth_more_than_an_anchor_reason_alone() {
    let dir = tempfile::tempdir().expect("tempdir");
    // An unanchored entry that is plainly being read has to outrank an anchor nobody
    // has touched, or the scoring would only ever protect the past. The anchor here
    // is the unique lowest score, so its deletion is the assertion.
    let mut store = SpillStore::open(&SpillConfig::new(dir.path(), 64)).expect("open");
    let never_read = write_fat(&mut store, b"never read", Reason::Evict, 0, AN_HOUR);
    let read_a_lot = write_fat(&mut store, b"read a lot", Reason::Continued, 40, AN_HOUR);
    let read_once = write_fat(&mut store, b"read once", Reason::AgentSystem, 2, AN_HOUR);
    drop(store);

    let reopened = SpillStore::open(&SpillConfig::new(dir.path(), 1)).expect("reopen");
    assert_eq!(reopened.stats().entries, 2);
    assert!(
        !reopened.contains(never_read),
        "an anchor with no evidence of use goes"
    );
    assert!(
        reopened.contains(read_a_lot),
        "evidence of use beats a reason code"
    );
    assert!(reopened.contains(read_once));
}

/// An hour, two hours and a minute in seconds: the ages the scoring tests stamp
/// entries with, chosen so the decay is a mild discount rather than an erasure.
const AN_HOUR: u64 = 3_600;
const TWO_HOURS: u64 = 7_200;
const A_MINUTE: u64 = 60;

#[test]
fn a_path_round_trips_through_the_payload_layout() {
    let header = path_header();
    let sections = path_sections();
    let bytes = encode_path(&header, &sections);
    assert_eq!(
        bytes.len(),
        usize::try_from(header.total_bytes().expect("sized")).expect("payload fits in an address")
    );
    let decoded = decode_path(&bytes, &header).expect("round trip");
    assert_eq!(decoded.header, header);
    assert_eq!(
        decoded.tokens,
        vec![TokenId::new(7), TokenId::new(8), TokenId::new(9)]
    );
    assert_eq!(decoded.logits, sections.logits);
    assert_eq!(decoded.state, sections.state);
    assert_eq!(decoded.pages.len(), 2);
    assert_eq!(decoded.pages[0], vec![0xa1u8; 8]);
    assert_eq!(decoded.pages[1], vec![0xb2u8; 8]);
}

#[test]
fn the_payload_header_words_are_in_the_documented_order() {
    let mut header = path_header();
    header.pending_draft_row = true;
    header.pending_pos0 = 2;
    // The record's field order IS the file's byte order, so the assertion is over the
    // bytes: a field reordered inside the struct would move a word on disk, and every
    // directory written by an older build would then read back shifted.
    let bytes = bytemuck::bytes_of(&header.to_words()).to_vec();
    assert_eq!(bytes.len(), 19 * 4, "the payload header is 19 words");
    let word = |at: usize| {
        let bytes: [u8; 4] = bytes[at * 4..at * 4 + 4]
            .try_into()
            .expect("a four-byte slice is four bytes");
        u32::from_le_bytes(bytes)
    };
    assert_eq!(&bytes[0..4], b"Q4EP");
    assert_eq!(word(1), 1, "the payload version this build writes");
    assert_eq!(word(2), header.page_bytes, "bytes per pool page");
    assert_eq!(word(3), header.tokens, "tokens in the path");
    assert_eq!(word(4), header.page_tokens, "positions per page");
    assert_eq!(word(5), header.pages, "logical pages");
    assert_eq!(word(12), header.vocab, "vocabulary");
    assert_eq!(word(17), 1, "a pending draft row follows");
    assert_eq!(word(18), 2, "its first position");
    // And the record reads back as itself, which is the other half of the contract.
    let read: PathWords = bytemuck::pod_read_unaligned(&bytes);
    assert_eq!(PathHeader::from_words(&read), header);
}

#[test]
fn a_toggle_disagreement_keeps_the_file_for_the_other_configuration() {
    let want = path_header();
    let mut written = path_header();
    written.indexer = true;
    let bytes = encode_path(&written, &path_sections());
    let error = decode_path(&bytes, &want).expect_err("the indexer toggle disagrees");
    assert_eq!(
        error,
        PathMismatch::Incompatible {
            field: "indexer caches",
            found: 1,
            want: 0
        },
        "a run without the indexer must not delete what a run with it wrote"
    );
}

#[test]
fn a_model_shape_disagreement_discards_the_file() {
    let want = path_header();
    let mut written = path_header();
    written.vocab += 1;
    let bytes = encode_path(&written, &path_sections());
    let error = decode_path(&bytes, &want).expect_err("a different vocabulary");
    assert_eq!(
        error,
        PathMismatch::Foreign {
            field: "vocabulary",
            found: 5,
            want: 4
        }
    );
}

#[test]
fn a_payload_shorter_than_its_own_header_is_refused() {
    let header = path_header();
    let mut bytes = encode_path(&header, &path_sections());
    let cut = bytes.len() - 4;
    bytes.truncate(cut);
    assert_eq!(
        decode_path(&bytes, &header).expect_err("truncated"),
        PathMismatch::Truncated {
            needed: header.total_bytes().expect("sized"),
            have: u64::try_from(cut).expect("fits")
        }
    );
}

#[test]
fn a_page_count_that_disagrees_with_the_length_is_discarded() {
    let want = path_header();
    let mut written = path_header();
    written.pages += 1;
    let bytes = encode_path(&written, &path_sections());
    let error = decode_path(&bytes, &want).expect_err("the page count lies");
    assert_eq!(
        error,
        PathMismatch::Foreign {
            field: "page count",
            found: 3,
            want: 2
        }
    );
}

#[test]
fn a_payload_from_another_build_is_discarded_rather_than_mis_parsed() {
    let header = path_header();
    let mut bytes = encode_path(&header, &path_sections());
    bytes[0..4].copy_from_slice(b"XXXX");
    assert_eq!(
        decode_path(&bytes, &header).expect_err("wrong magic"),
        PathMismatch::Foreign {
            field: "payload magic or version",
            found: 1,
            want: 1
        }
    );
}

/// A path shaped like a qwen35 one: no indexer, no draft head, no PLE window and no
/// hyper-connection plane, which is what the engine writes zeros for.
fn path_header() -> PathHeader {
    PathHeader {
        page_bytes: 8,
        tokens: 3,
        page_tokens: 2,
        pages: 2,
        kv_width: 4,
        n_layers: 32,
        n_attn_layers: 8,
        n_gdn_layers: 1,
        indexer: false,
        draft_head: false,
        vocab: 4,
        gdn_conv_elements: 8,
        gdn_state_elements: 16,
        ple_window_elements: 0,
        hc_width: 0,
        pending_draft_row: false,
        pending_pos0: 0,
    }
}

/// The four sections of [`path_header`]'s path, sized to match its header: three
/// tokens, a four-row logits row, one recurrent layer's window and matrix, and two
/// eight-byte pages.
#[must_use]
fn path_sections() -> PathSections<'static> {
    use std::sync::OnceLock;
    static SECTIONS: OnceLock<OwnedSections> = OnceLock::new();
    SECTIONS.get_or_init(OwnedSections::new).as_borrowed()
}

/// The same four sections, owned, so the borrowed view handed to `encode_path` has
/// somewhere stable to point at for as long as the process lives.
struct OwnedSections {
    tokens: Vec<TokenId>,
    logits: Vec<u8>,
    state: Vec<u8>,
    pages: Vec<u8>,
}

impl OwnedSections {
    fn new() -> Self {
        Self {
            tokens: vec![TokenId::new(7), TokenId::new(8), TokenId::new(9)],
            logits: vec![1u8; 16],
            state: vec![2u8; 96],
            pages: [vec![0xa1u8; 8], vec![0xb2u8; 8]].concat(),
        }
    }

    fn as_borrowed(&self) -> PathSections<'_> {
        PathSections {
            tokens: &self.tokens,
            logits: &self.logits,
            state: &self.state,
            pages: &self.pages,
        }
    }
}

fn incoming<'a>(text: &'a [u8], payload: &'a [u8], reason: Reason) -> Incoming<'a> {
    Incoming {
        text,
        tokens: 100,
        quant_bits: 4,
        model_id: 1,
        ctx_size: 8192,
        reason,
        ext_flags: 0,
        payload,
    }
}

/// Writes one entry, stamps its header with the read history the scoring pass is
/// supposed to price, and returns its id.
///
/// `seconds_ago` is an age rather than an absolute timestamp because the decay is
/// relative to now: a header stamped with a 1970 `last_used` has its hit count decayed
/// to nothing, which is the correct answer for such a file and a useless fixture.
fn write_fat(
    store: &mut SpillStore,
    text: &[u8],
    reason: Reason,
    hits: u32,
    seconds_ago: u64,
) -> SpillId {
    let payload = vec![0x33u8; FAT_PAYLOAD];
    let (SpillWrite::Written { id, .. } | SpillWrite::AlreadyStored { id }) = store
        .write(&incoming(text, &payload, reason))
        .expect("write")
    else {
        panic!("no other outcome")
    };
    let mut header = read_raw_header(&store.path_of(id));
    header.hits = hits;
    header.last_used = now_secs().saturating_sub(seconds_ago);
    stamp_header(&store.path_of(id), &header);
    id
}

/// Seconds since the epoch, from the same clock the store uses.
fn now_secs() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .expect("clock")
        .as_secs()
}

/// Replaces the 48 bytes at the front of an entry, leaving its body alone.
///
/// The store owns these fields when it writes, so a test that wants an entry with a
/// history has to give it one the way a previous run would have.
fn stamp_header(path: &Path, header: &SpillHeader) {
    let mut bytes = fs::read(path).expect("read entry");
    bytes[..HEADER_BYTES].copy_from_slice(&header.to_bytes());
    fs::write(path, bytes).expect("write entry");
}

fn read_raw_header(path: &Path) -> SpillHeader {
    let bytes = fs::read(path).expect("read entry");
    SpillHeader::from_bytes(bytes[..HEADER_BYTES].try_into().expect("48 bytes"))
}

/// Builds an entry file directly, so a test can create a file the writer would never
/// have produced.
fn write_raw(path: &Path, text: &[u8], payload: &[u8]) {
    let mut file = OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(path)
        .expect("create");
    file.write_all(&fixture_header().to_bytes())
        .expect("header");
    file.write_all(&(u32::try_from(text.len()).expect("len")).to_le_bytes())
        .expect("text length");
    file.write_all(text).expect("text");
    file.write_all(payload).expect("payload");
}

fn dir_files(dir: &Path) -> Vec<PathBuf> {
    let mut files: Vec<PathBuf> = fs::read_dir(dir)
        .expect("read_dir")
        .flatten()
        .map(|entry| entry.path())
        .collect();
    files.sort();
    files
}
